#include <stdio.h>
#include <string.h>
#include <stdlib.h>

int main(int argc, char **argv)
{
    if (argc < 2) {
        puts("BALANCED");
        return 0;
    }

    const char *s = argv[1];
    size_t len = strlen(s);
    char *stack = malloc(len + 1);
    size_t top = 0;

    for (size_t i = 0; i < len; ++i) {
        char c = s[i];
        if (c == '(' || c == '[' || c == '{') {
            stack[top++] = c;
            continue;
        }
        if (c == ')' || c == ']' || c == '}') {
            if (top == 0) {
                puts("UNBALANCED");
                free(stack);
                return 0;
            }
            char open = stack[--top];
            if ((c == ')' && open != '(') ||
                (c == ']' && open != '[') ||
                (c == '}' && open != '{')) {
                puts("UNBALANCED");
                free(stack);
                return 0;
            }
            continue;
        }
    }

    if (top == 0)
        puts("BALANCED");
    else
        puts("UNBALANCED");

    free(stack);
    return 0;
}
